// src/config/optimization.rs
#[derive(Debug, Clone)]
pub struct OptimizationConfig {
    // Bloom filter
    pub bloom_shards: usize,
    pub bloom_shard_size: usize,

    // Batching
    pub batch_size: usize,
    pub lsh_batch_size: usize,

    // Threading
    pub min_threads: usize,
    pub max_threads: usize,

    // Auto-tuning
    pub enable_auto_tune: bool,
}

impl OptimizationConfig {
    /// Auto-detect optimal parameters for current hardware
    pub fn auto_detect() -> Self {
        let cores = std::thread::available_parallelism().map(|n| n.get()).unwrap_or(1);
        let cache_size = Self::detect_l3_cache_size();

        Self {
            bloom_shards: cores.next_power_of_two(),
            bloom_shard_size: cache_size / cores / 2,
            batch_size: if cores >= 16 { 1000 } else { 500 },
            lsh_batch_size: if cores >= 16 { 1000 } else { 500 },
            min_threads: 2.min(cores),
            max_threads: cores,
            enable_auto_tune: true,
        }
    }

    /// Load from environment variables (12-factor app pattern)
    pub fn from_env() -> Result<Self, Error> {
        // Support KINDLY_BLOOM_SHARDS, KINDLY_BATCH_SIZE, etc.
    }
}

