// Consolidated event system (5 categories instead of 25+ types)
pub enum AuditCategory {
    Security,      // All protection-related events
    Operation,     // Pipeline execution events
    Performance,   // Metrics and monitoring
    Error,         // All error conditions
    Compliance,    // Regulatory audit events
}

pub struct AuditEvent {
    category: AuditCategory,
    event_type: String,  // Freeform for specific events
    severity: Severity,
    metadata: HashMap<String, String>,
    timestamp: SystemTime,
    hash: AtomicHash256,
}

