pub struct AuditDashboard {
    // ... existing fields ...
    last_update: AtomicU64,  // Timestamp of last update (ns)
    update_interval_ns: u64, // Adaptive interval
}

impl AuditDashboard {
    pub fn update_progress(&self, docs_processed: usize, throughput: f64) {
        let now = Instant::now();
        let elapsed_ns = now.duration_since(UNIX_EPOCH).as_nanos() as u64;
        let last = self.last_update.load(Ordering::Relaxed);

        // Adaptive throttling:
        // - Fast ops (>100K docs/sec): 100ms updates
        // - Medium ops (10-100K): 500ms updates
        // - Slow ops (<10K): 1000ms updates
        let interval = if throughput > 100_000.0 {
            100_000_000  // 100ms
        } else if throughput > 10_000.0 {
            500_000_000  // 500ms
        } else {
            1_000_000_000  // 1s
        };

        if elapsed_ns - last >= interval {
            self.last_update.store(elapsed_ns, Ordering::Relaxed);
            // Perform actual update...
        }
    }
}
